const tabs=[['vehicle','car','车辆'],['trips','route','行程'],['charging','bolt','充电'],['profile','user','我的']];
const nav=active=>`<nav class="tabbar" aria-label="主要页面">${tabs.map(([id,i,label])=>`<button data-page="${id}" class="${id===active?'active':''}" aria-label="${label}">${icon(i)}<span>${label}</span></button>`).join('')}<div class="home-indicator"></div></nav>`;
